<?php require_once __DIR__.'/../config.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['id'];$payment=$_POST['payment_status']??'';$production=$_POST['production_status']??'';if(in_array($payment,['waiting_payment','waiting_verification','approved','rejected'],true)&&in_array($production,['created','processing','completed'],true)){db()->prepare('UPDATE orders SET payment_status=?,production_status=? WHERE id=?')->execute([$payment,$production,$id]);if(in_array($payment,['approved','rejected'],true))db()->prepare('UPDATE payments SET status=?,verified_at=NOW() WHERE order_id=? AND status="waiting_verification"')->execute([$payment,$id]);flash('success','Status pesanan diperbarui.');}redirect('admin/orders.php');}$orders=db()->query('SELECT o.*,c.full_name,c.whatsapp,(SELECT proof_path FROM payments WHERE order_id=o.id ORDER BY id DESC LIMIT 1) proof FROM orders o JOIN customers c ON c.id=o.customer_id ORDER BY o.created_at DESC')->fetchAll();$adminTitle='Order & payment management';require __DIR__.'/_header.php';?><table class="data-table"><tr><th>Order</th><th>Customer</th><th>Total</th><th>Proof</th><th>Status</th><th>Update</th></tr><?php foreach($orders as $o):?><tr><td><b><?=e($o['order_number'])?></b><br><small><?=e($o['category_key'])?></small></td><td><?=e($o['full_name'])?><br><small><?=e($o['whatsapp'])?></small></td><td><?=money((float)$o['total'])?></td><td><?php if($o['proof']):?><a class="text-link" target="_blank" href="<?=url($o['proof'])?>">VIEW</a><?php else:?><small>—</small><?php endif;?></td><td><span class="status"><?=e($o['payment_status'])?></span><br><span class="status"><?=e($o['production_status'])?></span></td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$o['id']?>"><select name="payment_status" class="text-xs"><?php foreach(['waiting_payment','waiting_verification','approved','rejected'] as $s):?><option <?=$o['payment_status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><select name="production_status" class="text-xs"><option <?=$o['production_status']==='created'?'selected':''?>>created</option><option <?=$o['production_status']==='processing'?'selected':''?>>processing</option><option <?=$o['production_status']==='completed'?'selected':''?>>completed</option></select><button class="text-link border-0 bg-transparent cursor-pointer mt-2">SAVE</button></form></td></tr><?php endforeach;?></table><?php require __DIR__.'/_footer.php'; ?>
